CustomField.formula:
IF(Seats_Purchased_Override__c > 0, Seats_Purchased_Override__c,
IF(
    AND(
        Seats_Purchased_at_Approval__c > 0,
        ISPICKVAL(ApprovalStatus__c, 'Approved')
    ),
Seats_Purchased_at_Approval__c,
SBQQ__Account__r.Seats_Purchased1__c + Core_Quantity__c)
)

